pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address constant INITIAL_MIGRATOR = address(0);

    function setUp() public { 
        c = new C(address(this), address(this)); 
    }

    function testFuzz_property(address _rewardToken) public {
        vm.assume(_rewardToken != address(0) && _rewardToken != address(c));

        // Record migrator before any calls
        address migratorBefore = c.migrator();

        // Drive c through its public surface
        // We simulate a call to addReward which should not change migrator
        // Use try/catch in case addReward reverts (which is fine)
        try c.addReward(_rewardToken) {
            // success is fine
        } catch {
            // revert is fine, migrator still shouldn't change
        }

        address migratorAfter = c.migrator();

        // General rule: migrator never changes from its initial value
        assertTrue(migratorBefore == migratorAfter && migratorAfter == INITIAL_MIGRATOR);
    }
}

