pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }

    function testFuzz_property(address staker, uint256 stakeAmount) public {
        // Bound stakeAmount to avoid overflow issues (max 1e24 for practical testing)
        vm.assume(staker != address(0));
        vm.assume(stakeAmount > 0 && stakeAmount <= 1e24);

        // First, mint staking tokens to staker and approve them to this contract (which is also the owner)
        deal(address(c.stakingToken()), staker, stakeAmount);
        vm.prank(staker);
        IERC20(c.stakingToken()).approve(address(c), stakeAmount);

        // Stake tokens
        vm.prank(staker);
        c.stakeFor(staker, stakeAmount);

        // Check that balanceOf returns the same as the amount staked
        // Since we only staked once, the balance should equal stakeAmount
        assertTrue(c.balanceOf(staker) == stakeAmount, "balanceOf should return the staked amount");

        // Additionally, verify that after withdrawing, balanceOf returns 0
        vm.prank(staker);
        c.withdraw(stakeAmount, false);
        assertTrue(c.balanceOf(staker) == 0, "balanceOf should return 0 after full withdrawal");
    }
}

