pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address user, uint256 amount) public {
        vm.assume(amount > 0 && amount <= 1e30);
        vm.assume(user != address(0) && user != address(this));
        vm.deal(user, 1 ether);
        // Deploy a mock ERC20 for staking token (simple one)
        MockERC20 stakingToken = new MockERC20();
        stakingToken.mint(user, amount);
        // Replace c's staking token - we can't do that directly, so we deploy a new C with this token
        // Actually, the setUp uses address(this) as both stakingToken and distributor.
        // We need a stakingToken that user can approve and transfer. Use address(this) as StakingToken in setUp means address(this) must implement IERC20.
        // Simpler: Use a real ERC20 and construct C with it: 
        // But we must keep setUp verbatim? The instruction says "setUp() using the given new C(address(this), address(this)) verbatim".
        // So address(this) acts as stakingToken. We need address(this) to have IERC20 functionality for the test.
        // Let's make this contract an ERC20 for test purposes.
    }
}

contract MockERC20 {
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;
    function mint(address to, uint256 amount) public { balanceOf[to] += amount; }
    function approve(address spender, uint256 amount) public returns (bool) { allowance[msg.sender][spender] = amount; return true; }
    function transfer(address to, uint256 amount) public returns (bool) { require(balanceOf[msg.sender] >= amount); balanceOf[msg.sender] -= amount; balanceOf[to] += amount; return true; }
    function transferFrom(address from, address to, uint256 amount) public returns (bool) { require(allowance[from][msg.sender] >= amount); allowance[from][msg.sender] -= amount; require(balanceOf[from] >= amount); balanceOf[from] -= amount; balanceOf[to] += amount; return true; }
    function totalSupply() public view returns (uint256) { return 0; }
}

