pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address token) public {
        vm.assume(token != address(0) && token != address(this));
        // Ensure token is not already a reward token by calling addReward
        // We use a try/catch to handle revert if token already exists
        // First, we call addReward; if it reverts, we skip (token already added)
        // But for fuzzing we want a fresh token each time, so we assume it's not added.
        // Since we don't have a getter to check if token exists, we use vm.assume on a unique token.
        // We'll generate a deterministic unique token address from fuzz input.
        // Simpler: just call addReward and if it reverts, skip.
        // But we need a general rule that works for any added token.
        // We'll use a separate approach: always add a token that is unique by using the fuzz parameter to create a contract.
        // To keep it simple, we'll deploy a minimal ERC20 for each fuzz run.
        // But that would be heavy. Instead, we use vm.assume that the token is not the zero address and not the staking token.
        // However, the test might fail if token is already added. We'll just call addReward and assume it doesn't revert.
        // Actually, we can call addReward in a try block and if it reverts, we skip the assert.
        // But we need an assert that always applies. So we restrict fuzz to tokens not yet added.
        // Since setUp doesn't add any token, any token is fresh. So we just call addReward.
        c.addReward(token);
        // The rule: rewardPerTokenStored for that token equals 0 (since set in addReward)
        // We read rewardPerToken(token) which returns the stored value, should be 0.
        uint256 rpt = c.rewardPerToken(token);
        assertTrue(rpt == 0);
    }
}

