import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }

    function testFuzz_property(address rewardToken, uint96 rewardAmount) public {
        vm.assume(rewardToken != address(0));
        vm.assume(rewardAmount > 0 && rewardAmount % 86400 * 7 == 0); // ensure divisible by DURATION for simplicity

        // Add reward token
        c.addReward(rewardToken);

        // Transfer reward tokens to this contract to be used for notifyRewardAmount
        deal(rewardToken, address(this), rewardAmount);
        IERC20(rewardToken).approve(address(c), rewardAmount);

        // Notify reward amount
        c.notifyRewardAmount(rewardToken, rewardAmount);

        // Get the reward rate from the public getter (rewardData is public, so we access via auto-generated getter)
        (uint40 periodFinish, uint216 rewardRate, uint40 lastUpdateTime, uint216 rewardPerTokenStored) = c.rewardData(rewardToken);

        // The reward rate should be exactly rewardAmount / DURATION (since no leftover)
        // But we also need to consider that periodFinish is block.timestamp + DURATION
        // So the total reward distributed over the period is rewardRate * DURATION
        uint256 expectedTotalReward = uint256(rewardRate) * 86400 * 7;

        // Allow for a small rounding error due to integer division
        assertTrue(expectedTotalReward == rewardAmount || expectedTotalReward == rewardAmount - 1, "Reward rate does not match expected distribution");
    }
}

